INSERT INTO public.flashcards
  (id1, cn, pinyin, vocabulary, pinyin_vocab, th, sentence_test, translate, pinyin_sentence)
VALUES
(1001, '股', 'gǔ', '屁股', 'pì gǔ', 'ก้น', '小猴子的屁股总是红红的。', 'ก้นของลิงน้อยแดงอยู่เสมอ', 'xiǎo hóu zi de pì gǔ zǒng shì hóng hóng de'),
(1002, '写', 'xiě', '写字', 'xiě zì', 'เขียนหนังสือ', '一个小学生正在认真地练习写字。', 'นักเรียนประถมคนหนึ่งกำลังตั้งใจฝึกเขียนหนังสือ', 'yí gè xiǎo xué shēng zhèng zài rèn zhēn de liàn xí xiě zì'),
(1003, '枫', 'fēng', '枫叶', 'fēng yè', 'ใบเมเปิล', '秋天来了，山上的枫叶红成一片。', 'ฤดูใบไม้ร่วงมาถึง ใบเมเปิลบนภูเขาแดงเป็นพืด', 'qiū tiān lái le, shān shàng de fēng yè hóng chéng yí piàn'),
(1004, '柏', 'bǎi', '柏树', 'bǎi shù', 'ต้นไซเปรส/ต้นสน', '柏树是常青树，全年都是绿色的。', 'ต้นไซเปรสเป็นไม้ไม่ผลัดใบ เขียวตลอดทั้งปี', 'bǎi shù shì cháng qīng shù, quán nián dōu shì lǜ sè de'),
(1005, '坛', 'tán', '花坛', 'huā tán', 'แปลงดอกไม้', '小区里新建了一个漂亮的花坛。', 'ในหมู่บ้านสร้างแปลงดอกไม้สวยๆ ขึ้นใหม่แปลงหนึ่ง', 'xiǎo qū lǐ xīn jiàn le yí gè piào liang de huā tán'),
(1006, '何', 'hé', '任何', 'rèn hé', 'ใดๆ/ไม่ว่าอันไหน', '在任何困难面前都不能轻易低头。', 'ต่อหน้าอุปสรรคใดๆ ก็ห้ามยอมแพ้ง่ายๆ', 'zài rèn hé kùn nán miàn qián dōu bù néng qīng yì dī tóu'),
(1007, '杜', 'dù', '杜鹃', 'dù juān', 'ดอกกุหลาบพันปี/นกดุเหว่า', '春天，红艳艳的杜鹃花开满了山坡。', 'ฤดูใบไม้ผลิ ดอกกุหลาบพันปีสีแดงสดบานเต็มเนินเขา', 'chūn tiān, hóng yàn yàn de dù juān huā kāi mǎn le shān pō'),
(1008, '鹃', 'juān', '杜鹃鸟', 'dù juān niǎo', 'นกดุเหว่า', '初夏时节，杜鹃鸟不分日夜地叫着。', 'ช่วงต้นฤดูร้อน นกดุเหว่าร้องทั้งวันทั้งคืนไม่หยุด', 'chū xià shí jié, dù juān niǎo bù fēn rì yè de jiào zhe'),
(1009, '茂', 'mào', '茂盛', 'mào shèng', 'เขียวชอุ่ม/งอกงาม', '对面的山坡上长满了茂盛的青草。', 'บนเนินเขาฝั่งตรงข้ามปกคลุมด้วยหญ้าเขียวขจี', 'duì miàn de shān pō shàng zhǎng mǎn le mào shèng de qīng cǎo'),
(1010, '井', 'jǐng', '水井', 'shuǐ jǐng', 'บ่อน้ำ', '院子里有一口水井。', 'ในลานบ้านมีบ่อน้ำอยู่บ่อหนึ่ง', 'yuàn zi lǐ yǒu yì kǒu shuǐ jǐng'),
(1011, '藏', 'cáng', '埋藏', 'mái cáng', 'ฝังซ่อน', '这一带地下埋藏着丰富的矿产。', 'ใต้ดินแถบนี้ฝังทรัพยากรแร่ธาตุอันอุดมสมบูรณ์', 'zhè yí dài dì xià mái cáng zhe fēng fù de kuàng chǎn'),
(1012, '刨', 'páo', '刨出', 'páo chū', 'ขุด/คุ้ยออกมา', '农民伯伯在地里刨出了一块金子。', 'ลุงชาวนาขุดพบทองคำก้อนหนึ่งในไร่', 'nóng mín bó bo zài dì lǐ páo chū le yí kuài jīn zi'),
(1013, '腰', 'yāo', '腰部', 'yāo bù', 'เอว', '舞蹈课上，老师让大家先练习腰部。', 'ในคาบเรียนเต้น ครูให้ทุกคนฝึกช่วงเอวก่อน', 'wǔ dǎo kè shàng, lǎo shī ràng dà jiā xiān liàn xí yāo bù'),
(1014, '蹲', 'dūn', '蹲下', 'dūn xià', 'ย่อตัว/นั่งยองๆ', '妈妈蹲下来给了孩子一个拥抱。', 'แม่ย่อตัวลงกอดลูกหนึ่งที', 'mā mā dūn xià lái gěi le hái zi yí gè yōng bào'),
(1015, '由', 'yóu', '由于', 'yóu yú', 'เนื่องจาก', '由于大雪，比赛推迟到下周进行。', 'เนื่องจากหิมะตกหนัก การแข่งขันเลื่อนไปสัปดาห์หน้า', 'yóu yú dà xuě, bǐ sài tuī chí dào xià zhōu jìn xíng'),
(1016, '迈', 'mài', '迈步', 'mài bù', 'ก้าวเดิน', '无论遇到什么困难，都要迈步向前。', 'ไม่ว่าจะเจออุปสรรคอะไร ก็ต้องก้าวเดินไปข้างหน้า', 'wú lùn yù dào shén me kùn nán, dōu yào mài bù xiàng qián'),
(1017, '信', 'xìn', '明信片', 'míng xìn piàn', 'โปสการ์ด', '明信片上写满了我对朋友的祝福。', 'บนโปสการ์ดเขียนเต็มไปด้วยคำอวยพรที่ฉันมีให้เพื่อน', 'míng xìn piàn shàng xiě mǎn le wǒ duì péng yǒu de zhù fú'),
(1018, '恩', 'ēn', '感恩', 'gǎn ēn', 'สำนึกบุญคุณ/กตัญญู', '每个人都应该有一颗感恩的心。', 'ทุกคนควรมีหัวใจที่รู้จักสำนึกบุญคุณ', 'měi gè rén dōu yīng gāi yǒu yì kē gǎn ēn de xīn'),
(1019, '探', 'tàn', '试探', 'shì tàn', 'หยั่งเชิง/ลองหยั่ง', '他用竹竿试探了一下湖水的深浅。', 'เขาใช้ไม้ไผ่หยั่งดูความตื้นลึกของน้ำในทะเลสาบ', 'tā yòng zhú gān shì tàn le yí xià hú shuǐ de shēn qiǎn'),
(1020, '须', 'xū', '胡须', 'hú xū', 'หนวด', '爷爷留着长胡须，看起来很有趣。', 'คุณปู่ไว้หนวดยาว ดูน่าขบขันดี', 'yé ye liú zhe cháng hú xū, kàn qǐ lái hěn yǒu qù'),
(1021, '计', 'jì', '计算', 'jì suàn', 'คำนวณ', '数学老师给大家出了一道计算题。', 'ครูคณิตออกโจทย์คำนวณให้ทุกคนหนึ่งข้อ', 'shù xué lǎo shī gěi dà jiā chū le yí dào jì suàn tí'),
(1022, '需', 'xū', '需要', 'xū yào', 'ต้องการ/จำเป็น', '每个人都需要别人的理解和尊重。', 'ทุกคนต่างต้องการความเข้าใจและการเคารพจากผู้อื่น', 'měi gè rén dōu xū yào bié rén de lǐ jiě hé zūn zhòng'),
(1023, '缠', 'chán', '缠绕', 'chán rào', 'พันรอบ/ขดพัน', '一只小蛇把身体缠绕在树枝上。', 'งูน้อยตัวหนึ่งขดตัวพันรอบกิ่งไม้', 'yì zhī xiǎo shé bǎ shēn tǐ chán rào zài shù zhī shàng'),
(1024, '稀', 'xī', '稀有', 'xī yǒu', 'หายาก', '大熊猫是稀有动物，我们要保护它。', 'แพนด้ายักษ์เป็นสัตว์หายาก เราต้องปกป้องมัน', 'dà xióng māo shì xī yǒu dòng wù, wǒ men yào bǎo hù tā'),
(1025, '指', 'zhǐ', '手指', 'shǒu zhǐ', 'นิ้วมือ', '用手指指着别人说话是不礼貌的。', 'การใช้นิ้วชี้ไปที่คนอื่นเวลาพูดเป็นเรื่องไม่สุภาพ', 'yòng shǒu zhǐ zhǐ zhe bié rén shuō huà shì bù lǐ mào de'),
(1026, '哄', 'hǒng', '哄小孩', 'hǒng xiǎo hái', 'กล่อมเด็ก', '妈妈轻声唱着摇篮曲哄小孩睡觉。', 'แม่ร้องเพลงกล่อมเบาๆ กล่อมลูกให้หลับ', 'mā mā qīng shēng chàng zhe yáo lán qǔ hǒng xiǎo hái shuì jiào'),
(1027, '概', 'gài', '大概', 'dà gài', 'คงจะ/ประมาณ', '他大概太累了，睡了一天一夜。', 'เขาคงจะเหนื่อยมาก นอนไปหนึ่งวันหนึ่งคืน', 'tā dà gài tài lèi le, shuì le yì tiān yí yè'),
(1028, '粒', 'lì', '一粒米', 'yí lì mǐ', 'ข้าวหนึ่งเม็ด', '饭桌上的每一粒米都来之不易。', 'ข้าวทุกเม็ดบนโต๊ะอาหารล้วนได้มาไม่ง่าย', 'fàn zhuō shàng de měi yí lì mǐ dōu lái zhī bú yì'),
(1029, '微', 'wēi', '微小', 'wēi xiǎo', 'เล็กน้อย/จิ๋ว', '我为自己每个微小的进步感到高兴。', 'ฉันดีใจกับความก้าวหน้าเล็กๆ น้อยๆ ของตัวเองทุกครั้ง', 'wǒ wèi zì jǐ měi gè wēi xiǎo de jìn bù gǎn dào gāo xìng'),
(1030, '册', 'cè', '册子', 'cè zi', 'สมุด/เล่มเล็ก', '这个景点为游人印了好多小册子。', 'สถานที่ท่องเที่ยวแห่งนี้พิมพ์สมุดเล่มเล็กให้นักท่องเที่ยวมากมาย', 'zhè ge jǐng diǎn wèi yóu rén yìn le hǎo duō xiǎo cè zi'),
(1031, '钟', 'zhōng', '钟表', 'zhōng biǎo', 'นาฬิกา', '他喜欢收藏各式各样的钟表。', 'เขาชอบสะสมนาฬิกาหลากหลายแบบ', 'tā xǐ huān shōu cáng gè shì gè yàng de zhōng biǎo'),
(1032, '敬', 'jìng', '敬礼', 'jìng lǐ', 'ทำความเคารพ/วันทยหัตถ์', '天安门广场上，军人在向五星红旗敬礼。', 'ที่จัตุรัสเทียนอันเหมิน ทหารกำลังทำความเคารพธงแดงห้าดาว', 'tiān ān mén guǎng chǎng shàng, jūn rén zài xiàng wǔ xīng hóng qí jìng lǐ'),
(1033, '割', 'gē', '割掉', 'gē diào', 'ตัดทิ้ง/เฉือนออก', '农夫割掉了被害虫咬坏的枝叶。', 'ชาวนาตัดกิ่งใบที่ถูกแมลงกัดกินทิ้งไป', 'nóng fū gē diào le bèi hài chóng yǎo huài de zhī yè'),
(1034, '宣', 'xuān', '宣读', 'xuān dú', 'อ่านประกาศ', '队长向大家宣读了下一步的安排。', 'หัวหน้าทีมอ่านประกาศแผนขั้นต่อไปให้ทุกคนฟัง', 'duì zhǎng xiàng dà jiā xuān dú le xià yí bù de ān pái'),
(1035, '席', 'xí', '凉席', 'liáng xí', 'เสื่อ (คลายร้อน)', '天气太热了，躺在凉席上休息下吧！', 'อากาศร้อนมาก นอนพักบนเสื่อกันเถอะ!', 'tiān qì tài rè le, tǎng zài liáng xí shàng xiū xi xià ba'),
(1036, '申', 'shēn', '重申', 'chóng shēn', 'ย้ำอีกครั้ง', '他在会议中重申了自己的观点。', 'เขาย้ำจุดยืนของตัวเองอีกครั้งในที่ประชุม', 'tā zài huì yì zhōng chóng shēn le zì jǐ de guān diǎn'),
(1037, '架', 'jià', '书架', 'shū jià', 'ชั้นหนังสือ', '家里的书架上放了很多书。', 'บนชั้นหนังสือที่บ้านวางหนังสือไว้มากมาย', 'jiā lǐ de shū jià shàng fàng le hěn duō shū'),
(1038, '搬', 'bān', '搬运', 'bān yùn', 'ขนย้าย', '工人们正在把行李搬运上船。', 'คนงานกำลังขนสัมภาระขึ้นเรือ', 'gōng rén men zhèng zài bǎ xíng li bān yùn shàng chuán'),
(1039, '建', 'jiàn', '建造', 'jiàn zào', 'สร้าง/ก่อสร้าง', '村民要在路边建造一座五层小楼。', 'ชาวบ้านจะสร้างตึกห้าชั้นหลังเล็กไว้ริมถนน', 'cūn mín yào zài lù biān jiàn zào yí zuò wǔ céng xiǎo lóu'),
(1040, '梁', 'liáng', '桥梁', 'qiáo liáng', 'สะพาน', '语言是人们相互交流的桥梁。', 'ภาษาคือสะพานเชื่อมการสื่อสารระหว่างผู้คน', 'yǔ yán shì rén men xiāng hù jiāo liú de qiáo liáng'),
(1041, '泥', 'ní', '泥泞', 'ní nìng', 'เฉอะแฉะ/เป็นโคลน', '他不顾道路泥泞，步行回家去了。', 'เขาไม่สนใจว่าถนนจะเป็นโคลน เดินกลับบ้านไป', 'tā bú gù dào lù ní nìng, bù xíng huí jiā qù le'),
(1042, '岭', 'lǐng', '山岭', 'shān lǐng', 'ทิวเขา/สันเขา', '透过窗户，可以看见远处的山岭。', 'มองผ่านหน้าต่างออกไป เห็นทิวเขาที่อยู่ไกลๆ', 'tòu guò chuāng hù, kě yǐ kàn jiàn yuǎn chù de shān lǐng'),
(1043, '趴', 'pā', '趴下', 'pā xià', 'หมอบลง', '将军叫士兵们站直了，别趴下。', 'แม่ทัพสั่งให้ทหารยืนตรง อย่าหมอบลง', 'jiāng jūn jiào shì bīng men zhàn zhí le, bié pā xià'),
(1044, '砸', 'zá', '砸开', 'zá kāi', 'ทุบให้แตก', '他一使劲，把水缸砸开了一个洞。', 'เขาออกแรงทุบโอ่งน้ำจนแตกเป็นรู', 'tā yì shǐ jìn, bǎ shuǐ gāng zá kāi le yí gè dòng'),
(1045, '骗', 'piàn', '哄骗', 'hǒng piàn', 'หลอกลวง', '不要被坏人的甜言蜜语哄骗了。', 'อย่าถูกคำหวานของคนชั่วหลอกเชียวนะ', 'bú yào bèi huài rén de tián yán mì yǔ hǒng piàn le'),
(1046, '梢', 'shāo', '末梢', 'mò shāo', 'ปลายสุด/ยอด', '大树的末梢处又长出了新的枝叶。', 'ที่ปลายยอดของต้นไม้ใหญ่แตกกิ่งใบใหม่ออกมาอีก', 'dà shù de mò shāo chù yòu zhǎng chū le xīn de zhī yè'),
(1047, '锋', 'fēng', '锋利', 'fēng lì', 'คม', '将军有一把锋利无比的宝刀。', 'แม่ทัพมีดาบวิเศษที่คมกริบเล่มหนึ่ง', 'jiāng jūn yǒu yì bǎ fēng lì wú bǐ de bǎo dāo'),
(1048, '迹', 'jì', '足迹', 'zú jì', 'รอยเท้า', '那只狗沿着狐狸的足迹跑进了树林。', 'สุนัขตัวนั้นวิ่งตามรอยเท้าจิ้งจอกเข้าไปในป่า', 'nà zhī gǒu yán zhe hú li de zú jì pǎo jìn le shù lín'),
(1049, '冒', 'mào', '感冒', 'gǎn mào', 'เป็นหวัด', '感冒发烧了可以用热毛巾帮助散热。', 'เป็นหวัดตัวร้อนใช้ผ้าขนหนูอุ่นช่วยระบายความร้อนได้', 'gǎn mào fā shāo le kě yǐ yòng rè máo jīn bāng zhù sàn rè'),
(1050, '沟', 'gōu', '水沟', 'shuǐ gōu', 'ร่องน้ำ/คูน้ำ', '他一下子就跳过了那条小水沟。', 'เขากระโดดข้ามร่องน้ำเล็กๆ นั้นไปในทีเดียว', 'tā yí xià zi jiù tiào guò le nà tiáo xiǎo shuǐ gōu');
